    norm = filename.replace("./", "") if filename else "mod.css"
    if norm in mapping: return mapping[norm]
    h = 5381
    for char in norm: h = ((h << 5) + h) + ord(char); h &= 0xFFFFFFFF
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
    res = ""
    for _ in range(6): res += alphabet[h % len(alphabet)]; h //= len(alphabet)
    return res

