    p = val.split()
    if len(p) == 4 and p[1] == p[3]: p = p[:3]
    if len(p) == 3 and p[0] == p[2]: p = p[:2]
    if len(p) == 2 and p[0] == p[1]: p = p[:1]
    return " ".join(p)

def optimize_decls(decls):
    margin = [None]*4
    padding = [None]*4
    other = []
    for prop, val in decls:
        if prop == 'margin-top': margin[0] = val
        elif prop == 'margin-right': margin[1] = val
        elif prop == 'margin-bottom': margin[2] = val
        elif prop == 'margin-left': margin[3] = val
        elif prop == 'margin':
            m = val.split()
            if len(m)==1: margin=[m[0]]*4
            elif len(m)==2: margin=[m[0],m[1],m[0],m[1]]
            elif len(m)==3: margin=[m[0],m[1],m[2],m[1]]
            elif len(m)==4: margin=m
        elif prop == 'padding-top': padding[0] = val
        elif prop == 'padding-right': padding[1] = val
        elif prop == 'padding-bottom': padding[2] = val
        elif prop == 'padding-left': padding[3] = val
        elif prop == 'padding':
            p = val.split()
            if len(p)==1: padding=[p[0]]*4
            elif len(p)==2: padding=[p[0],p[1],p[0],p[1]]
            elif len(p)==3: padding=[p[0],p[1],p[2],p[1]]
